import React, { useState } from 'react';

// Mock data for today's time tracking
const timeTrackerData = [
  { id: 'TCS101', name: 'Dr. Anjali Rao', department: 'Computer Science', clockIn: '09:02 AM', clockOut: '--', totalHours: '--', status: 'Working' },
  { id: 'PHY102', name: 'Dr. Vikram Kumar', department: 'Physics', clockIn: '09:30 AM', clockOut: '05:35 PM', totalHours: '8h 5m', status: 'Completed' },
  { id: 'ADM003', name: 'Sunita Sharma', department: 'Admissions Office', clockIn: '08:55 AM', clockOut: '--', totalHours: '--', status: 'Working' },
  { id: 'LIB004', name: 'Rajesh Singh', department: 'Library', clockIn: '--', clockOut: '--', totalHours: '--', status: 'On Leave' },
  { id: 'MGT001', name: 'Dr. Priya Mehta', department: 'Administration', clockIn: '09:15 AM', clockOut: '06:00 PM', totalHours: '8h 45m', status: 'Completed' },
  { id: 'ENG205', name: 'Amit Desai', department: 'Engineering', clockIn: '10:00 AM', clockOut: '--', totalHours: '--', status: 'Working' },
];

const TimeTrackerPage = () => {
  // State to manage the current view mode ('Daily', 'Weekly', 'Monthly')
  const [viewMode, setViewMode] = useState('Daily');
  // State to manage the selected date, initialized to today's date in YYYY-MM-DD format
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().slice(0, 10));

  const getStatusBadgeClass = (status) => {
    switch (status) {
      case 'Working': return 'bg-blue-100 text-blue-800';
      case 'Completed': return 'bg-green-100 text-green-800';
      case 'On Leave': return 'bg-yellow-100 text-yellow-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <div className="flex flex-col h-full">
      <header className="bg-card-light dark:bg-card-dark p-4 border-b border-border-light dark:border-border-dark flex-shrink-0">
        <div className="flex flex-wrap justify-between items-center gap-4">
          {/* Left Side: Title and View Mode */}
          <div className="flex items-center space-x-4">
            <h1 className="text-2xl font-semibold text-text-light dark:text-text-dark">Time Tracker</h1>
            {/* View Mode Buttons */}
            <div className="flex items-center bg-gray-200 dark:bg-gray-700 p-1 rounded-lg">
                <button onClick={() => setViewMode('Daily')} className={`px-3 py-1 text-sm font-medium rounded-md ${viewMode === 'Daily' ? 'bg-white dark:bg-gray-900 shadow' : 'text-subtext-light'}`}>Daily</button>
                <button onClick={() => setViewMode('Weekly')} className={`px-3 py-1 text-sm font-medium rounded-md ${viewMode === 'Weekly' ? 'bg-white dark:bg-gray-900 shadow' : 'text-subtext-light'}`}>Weekly</button>
                <button onClick={() => setViewMode('Monthly')} className={`px-3 py-1 text-sm font-medium rounded-md ${viewMode === 'Monthly' ? 'bg-white dark:bg-gray-900 shadow' : 'text-subtext-light'}`}>Monthly</button>
            </div>
          </div>

          {/* Right Side: Date Navigation and Export */}
          <div className="flex items-center space-x-4">
            {/* Date Navigation */}
            <div className="flex items-center space-x-2">
                <button className="p-1 rounded-md hover:bg-gray-200 dark:hover:bg-gray-700">
                    <span className="material-icons text-subtext-light">chevron_left</span>
                </button>
                <input 
                  type="date" 
                  value={selectedDate}
                  onChange={(e) => setSelectedDate(e.target.value)}
                  className="bg-card-light dark:bg-gray-800 border-border-light dark:border-border-dark rounded-md shadow-sm p-1.5 text-sm"
                />
                <button className="p-1 rounded-md hover:bg-gray-200 dark:hover:bg-gray-700">
                    <span className="material-icons text-subtext-light">chevron_right</span>
                </button>
            </div>
            <button className="bg-primary text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center hover:bg-blue-600">
              <span className="material-icons mr-2 text-base">download</span> Export Report
            </button>
          </div>
        </div>
      </header>

      <div className="p-8">
        {/* Filter Bar */}
        <div className="mb-6">
            <label htmlFor="department-filter" className="block text-sm font-medium text-subtext-light dark:text-subtext-dark mb-1">Filter by Department</label>
            <select id="department-filter" name="department" className="w-full md:w-1/3 bg-card-light dark:bg-gray-800 border-border-light dark:border-border-dark rounded-md shadow-sm appearance-none pr-8">
                <option>All Departments</option>
                <option>Faculty of Engineering</option>
                <option>Faculty of Arts & Commerce</option>
            </select>
        </div>

        {/* Time Tracker Table */}
        <div className="overflow-x-auto rounded-lg border border-border-light dark:border-border-dark bg-card-light dark:bg-card-dark">
          <table className="w-full text-sm text-left">
            <thead className="text-xs text-subtext-light dark:text-subtext-dark uppercase bg-background-light dark:bg-background-dark">
              <tr>
                <th className="px-6 py-3">Employee Name</th>
                <th className="px-6 py-3">Department</th>
                <th className="px-6 py-3">Clock In</th>
                <th className="px-6 py-3">Clock Out</th>
                <th className="px-6 py-3">Total Hours</th>
                <th className="px-6 py-3">Status</th>
              </tr>
            </thead>
            <tbody>
              {timeTrackerData.map((entry) => (
                <tr key={entry.id} className="border-b border-border-light dark:border-border-dark hover:bg-gray-50 dark:hover:bg-gray-800/50">
                  <td className="px-6 py-4 font-medium text-text-light dark:text-text-dark">{entry.name}</td>
                  <td className="px-6 py-4">{entry.department}</td>
                  <td className="px-6 py-4">{entry.clockIn}</td>
                  <td className="px-6 py-4">{entry.clockOut}</td>
                  <td className="px-6 py-4 font-semibold">{entry.totalHours}</td>
                  <td className="px-6 py-4">
                    <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getStatusBadgeClass(entry.status)}`}>
                      {entry.status}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default TimeTrackerPage;
